export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export class Crossing {
 constructor(random=Math.random){this.random=random;this.reset('run');this.phase='menu'}
 reset(mode){this.mode=mode;this.phase='play';this.time=0;this.sector=1;this.score=0;this.combo=1;this.comboTime=0;this.stopped=0;this.escaped=0;this.delivered=0;this.entities=[];this.shots=[];this.events=[];this.id=0;this.spawn=1;this.pickup=9;this.player={x:0,z:23,vx:0,vz:0,hull:100,boost:100,cooldown:0,invincible:2,decoy:0};this.upgrades={engine:0,ability:0};this.input={x:0,z:0,boost:false,fire:false,aim:null};}
 event(type,data={}){this.events.push({type,...data})}
 add(type,x,z,extra={}){const e={id:++this.id,type,x,z,vx:0,vz:0,age:0,hp:type==='tanker'?4:type==='escort'?3:1,r:type==='tanker'?3.4:type==='escort'?2.1:1.4,cool:1+this.random()*2,...extra};this.entities.push(e);return e}
 reward(n){this.score+=n*this.combo;this.comboTime=7;this.combo=Math.min(5,this.combo+1)}
 damage(n){if(this.player.invincible>0)return;this.player.hull=Math.max(0,this.player.hull-n);this.player.invincible=1.2;this.combo=1;this.event('hit',{x:this.player.x,z:this.player.z});if(!this.player.hull)this.end(false)}
 end(win){if(this.phase!=='play')return;this.phase='end';this.win=win;if(win)this.score+=Math.round(this.player.hull)*20;this.event('end',{win})}
 ability(){const p=this.player;if(this.phase!=='play'||p.cooldown>0)return;if(this.mode==='run'){p.decoy=3.2;p.cooldown=10/(1+this.upgrades.ability*.8);this.event('decoy',{x:p.x,z:p.z});}else{let aim=this.input.aim;if(!aim){const target=this.entities.filter(e=>['tanker','escort'].includes(e.type)&&e.z<p.z+4).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0];aim=target??{x:p.x,z:p.z-50}}let dx=aim.x-p.x,dz=aim.z-p.z,d=Math.hypot(dx,dz)||1;this.shots.push({id:++this.id,x:p.x,z:p.z-2,vx:dx/d*76,vz:dz/d*76,age:0});p.cooldown=.28/(1+this.upgrades.ability*.4);this.event('fire',{x:p.x,z:p.z});}}
 upgrade(kind){if(this.phase!=='upgrade')return;if(!['repair','engine','ability'].includes(kind))throw new Error('Invalid upgrade');if(kind==='repair')this.player.hull=clamp(this.player.hull+45,0,100);else this.upgrades[kind]++;this.phase='play';this.player.invincible=2.5;this.event('sector',{sector:this.sector})}
 tick(dt){if(this.phase!=='play')return;dt=Math.min(dt,.05);const p=this.player;this.time+=dt;this.comboTime-=dt;if(this.comboTime<=0)this.combo=1;p.cooldown=Math.max(0,p.cooldown-dt);p.invincible=Math.max(0,p.invincible-dt);p.decoy=Math.max(0,p.decoy-dt);const boosting=this.input.boost&&p.boost>1;this.boosting=boosting;p.boost=clamp(p.boost+(boosting?-32:13+this.upgrades.engine*4)*dt,0,100);const speed=(this.mode==='run'?20:23)*(1+this.upgrades.engine*.2)*(boosting?1.75:1);let ix=this.input.x,iz=this.input.z,len=Math.hypot(ix,iz);if(len>1){ix/=len;iz/=len}p.vx+=(ix*speed-p.vx)*Math.min(1,dt*6);p.vz+=(iz*speed-p.vz)*Math.min(1,dt*6);p.x=clamp(p.x+p.vx*dt,-30,30);p.z=clamp(p.z+p.vz*dt,-14,34);if(this.input.fire)this.ability();
 this.spawn-=dt;this.pickup-=dt;if(this.spawn<=0){this.spawn=(this.mode==='run'?1.3:2.3)/(1+(this.sector-1)*.25)+this.random()*.45;const x=(this.random()-.5)*52;if(this.mode==='run'){const type=this.random()<.3?'mine':'escort';this.add(type,x,-60,{vz:type==='mine'?12:11+this.sector*2});if(this.sector>1&&this.random()<.2)this.add('mine',clamp(x+12,-28,28),-65,{vz:13});}else this.add(this.random()<.23?'escort':'tanker',x,-65,{vz:8+this.sector*2});}
 if(this.pickup<=0){this.pickup=10+this.random()*5;this.add('repair',(this.random()-.5)*48,-58,{vz:12})}
 const remove=new Set();for(const e of [...this.entities]){e.age+=dt;e.cool-=dt;e.z+=e.vz*dt;if(e.type==='escort'){e.x=clamp(e.x+Math.sin(e.age*1.4+e.id)*dt*2.5,-29,29);if(e.cool<=0&&e.z<p.z-6&&e.z>-42){e.cool=Math.max(1.5,3.6-this.sector*.5);const dx=p.x-e.x,dz=p.z-e.z,d=Math.hypot(dx,dz)||1;this.add('missile',e.x,e.z+2,{vx:dx/d*19,vz:dz/d*19,r:.8});this.event('enemyfire',{x:e.x,z:e.z})}}
 if(e.type==='missile'){if(p.decoy>0){e.vx+=(e.x-p.x)*dt*2;e.vz+=dt*8;}e.x+=e.vx*dt;}
 if(e.z>48||Math.abs(e.x)>55||e.age>18){remove.add(e);if(this.mode==='block'&&e.type==='tanker'){this.escaped++;this.player.hull=Math.max(0,this.player.hull-16);this.combo=1;this.event('escaped');if(!this.player.hull)this.end(false)}else if(this.mode==='run'&&['mine','escort'].includes(e.type))this.score+=30;continue;}
 if(Math.hypot(e.x-p.x,e.z-p.z)<e.r+1.4){if(e.type==='repair'){p.hull=clamp(p.hull+22,0,100);p.boost=clamp(p.boost+30,0,100);this.reward(75);remove.add(e);this.event('repair',{x:e.x,z:e.z})}else{this.damage(e.type==='missile'?18:e.type==='mine'?28:23);if(e.type!=='tanker')remove.add(e)}}}
 const deadShots=new Set();for(const s of this.shots){s.age+=dt;s.x+=s.vx*dt;s.z+=s.vz*dt;if(s.age>1.9){deadShots.add(s);continue}for(const e of this.entities){if(remove.has(e)||!['tanker','escort','mine'].includes(e.type))continue;if(Math.hypot(e.x-s.x,e.z-s.z)<e.r+1){e.hp--;deadShots.add(s);this.event('impact',{x:s.x,z:s.z});if(e.hp<=0){remove.add(e);this.reward(e.type==='tanker'?250:150);this.stopped++;this.event('destroy',{x:e.x,z:e.z,big:e.type==='tanker'});if(this.random()<.2)this.add('repair',e.x,e.z,{vz:7})}break}}}
 this.entities=this.entities.filter(e=>!remove.has(e));this.shots=this.shots.filter(s=>!deadShots.has(s));if(this.phase!=='play')return;if(this.time>=105){if(this.mode==='run')this.delivered++;this.end(true);return}const next=1+Math.floor(this.time/35);if(next>this.sector){this.sector=next;this.delivered+=this.mode==='run'?1:0;this.score+=1000;this.entities=this.entities.filter(e=>e.z<-20);this.shots=[];this.phase='upgrade';this.event('upgrade')}
 }
}
